package tri_lion.health.domain.routine;import jakarta.persistence.*;import lombok.*;
@Entity@Table(name="routine_sections")@Getter@NoArgsConstructor(access=AccessLevel.PROTECTED)public class RoutineSection{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="section_id")private Long id;@Column(name="routine_day_id")private Long routineDayId;@Enumerated(EnumType.STRING)@Column(name="section_type")private Type type;private String title;@Column(name="sort_order")private int sortOrder;public RoutineSection(Long day,Type type,String title,int order){routineDayId=day;this.type=type;this.title=title;sortOrder=order;}public enum Type{WARM_UP,MAIN_EXERCISE,COOL_DOWN}}
